import 'package:flutter/material.dart';

class RegisterPage extends StatefulWidget {
  const RegisterPage({super.key});

  @override
  State<RegisterPage> createState() => _RegisterPageState();
}

class _RegisterPageState extends State<RegisterPage> {
  final _formKey = GlobalKey<FormState>();
  final _nama = TextEditingController();
  final _email = TextEditingController();
  final _password = TextEditingController();
  bool _showPassword = false;

  @override
  void dispose() {
    _nama.dispose();
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  void _daftar() {
    if (_formKey.currentState?.validate() ?? false) {
      // Panggil API register
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Pendaftaran berhasil!')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Daftar Akun')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _nama,
                decoration: const InputDecoration(
                  labelText: 'Nama Lengkap',
                  prefixIcon: Icon(Icons.person),
                  border: OutlineInputBorder(),
                ),
                validator: (v) =>
                    (v == null || v.isEmpty) ? 'Nama wajib diisi' : null,
              ),
              const SizedBox(height: 16),
              TextFormField(
                controller: _email,
                keyboardType: TextInputType.emailAddress,
                decoration: const InputDecoration(
                  labelText: 'Email',
                  prefixIcon: Icon(Icons.email),
                  border: OutlineInputBorder(),
                ),
                validator: (v) {
                  if (v == null || v.isEmpty) return 'Email wajib diisi';
                  if (!v.contains('@')) return 'Email tidak valid';
                  return null;
                },
              ),
              const SizedBox(height: 16),
              TextFormField(
                controller: _password,
                obscureText: !_showPassword,
                decoration: InputDecoration(
                  labelText: 'Password',
                  prefixIcon: const Icon(Icons.lock),
                  border: const OutlineInputBorder(),
                  suffixIcon: IconButton(
                    icon: Icon(_showPassword
                        ? Icons.visibility_off
                        : Icons.visibility),
                    onPressed: () =>
                        setState(() => _showPassword = !_showPassword),
                  ),
                ),
                validator: (v) => (v == null || v.length < 8)
                    ? 'Minimal 8 karakter'
                    : null,
              ),
              const SizedBox(height: 24),
              SizedBox(
                width: double.infinity,
                height: 50,
                child: ElevatedButton(
                  onPressed: _daftar,
                  child: const Text('Daftar Sekarang'),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

function hitungDiskon(harga) {
    let diskon = 0;

    if (harga >= 100000 && harga < 250000) {
        diskon = 5;          // 5%
    } else if (harga >= 250000 && harga < 500000) {
        diskon = 10;         // 10%
    } else if (harga >= 500000) {
        diskon = 15;         // 15%
    }

    const potongan = (harga * diskon) / 100;
    const total = harga - potongan;

    return {
        harga,
        diskon: diskon + '%',
        potongan,
        total,
        keterangan: diskon === 0
            ? 'Belum dapat diskon'
            : `Diskon ${diskon}% = Rp ${potongan.toLocaleString('id-ID')}`
    };
}

console.log(hitungDiskon(600000));
// { harga: 600000, diskon: '15%', potongan: 90000, total: 510000, ... }

import 'package:flutter/material.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatefulWidget {
  const MyApp({super.key});

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  bool _darkMode = false;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      themeMode: _darkMode ? ThemeMode.dark : ThemeMode.light,
      theme: ThemeData.light(useMaterial3: true),
      darkTheme: ThemeData.dark(useMaterial3: true),
      home: Scaffold(
        appBar: AppBar(
          title: const Text('Mode Gelap'),
          actions: [
            IconButton(
              icon: Icon(_darkMode ? Icons.light_mode : Icons.dark_mode),
              onPressed: () => setState(() => _darkMode = !_darkMode),
            ),
          ],
        ),
        body: Center(
          child: Text(
            _darkMode ? 'Mode gelap aktif' : 'Mode terang aktif',
            style: const TextStyle(fontSize: 18),
          ),
        ),
      ),
    );
  }
}

function formatRupiah(angka) {
    return 'Rp ' + Math.round(angka)
        .toString()
        .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

// Pakai toLocaleString (cara simpel)
function formatRupiah2(angka) {
    return 'Rp ' + Number(angka).toLocaleString('id-ID');
}

// Parsing balik: hapus Rp, titik, spasi
function parseRupiah(str) {
    const bersih = str.replace(/[^\d]/g, '');
    return parseInt(bersih || '0', 10);
}

console.log(formatRupiah(1500000));   // Rp 1.500.000
console.log(formatRupiah2(2500000));  // Rp 2.500.000
console.log(parseRupiah('Rp 1.500.000')); // 1500000

